-- Migration: 000048_deepen_n4_n3_curriculum_and_exams.up.sql
-- Description: Deepen JLPT N4 and N3 curriculum to 7 lessons/unit x 8 exercises/lesson
--              and add N4 & N3 Readiness Mock Exams (diagnostic_exam, order_index = 99).
--              Total new content: 40 curriculum lessons, 2 diagnostic exams, 540 exercises.

DO $$
DECLARE
    v_n4_level_id uuid;
    v_n3_level_id uuid;
    v_unit_id uuid;
    v_lesson_id uuid;
    v_gp_id uuid;
BEGIN
    SELECT pl.id INTO v_n4_level_id
    FROM proficiency_levels pl
    JOIN languages l ON l.id = pl.language_id
    WHERE l.code = 'ja' AND pl.code = 'N4'
    LIMIT 1;

    SELECT pl.id INTO v_n3_level_id
    FROM proficiency_levels pl
    JOIN languages l ON l.id = pl.language_id
    WHERE l.code = 'ja' AND pl.code = 'N3'
    LIMIT 1;

    -- =========================================================================
    -- JLPT N4: Deepen Units 1..10 (7 lessons/unit x 8 exercises) + Mock Exam
    -- =========================================================================
    IF v_n4_level_id IS NOT NULL THEN
        -- Idempotent cleanup of any prior run of 000048 for N4
        DELETE FROM units WHERE level_id = v_n4_level_id AND unit_type = 'diagnostic_exam' AND order_index = 99;
        DELETE FROM lessons WHERE slug LIKE 'n4-u%-baca-konteks' OR slug LIKE 'n4-u%-praktik-terpadu';
        DELETE FROM exercises
        WHERE order_index IN (7, 8)
          AND lesson_id IN (SELECT id FROM lessons WHERE slug LIKE 'n4-u%');
        UPDATE lessons SET order_index = 7 WHERE slug LIKE 'n4-u%-tes-akhir';

        -- N4 Unit 1 (GP-JA-N4-001)
        SELECT id INTO v_unit_id FROM units WHERE level_id = v_n4_level_id AND unit_type = 'curriculum' AND order_index = 1 LIMIT 1;
        SELECT id INTO v_gp_id FROM grammar_points WHERE code = 'GP-JA-N4-001' LIMIT 1;
        IF v_unit_id IS NOT NULL THEN
            INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
