            RETURNING id INTO v_lesson_id;
        INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
        VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: メールの添付ファイルが開けないので、もう一度___いただけませんか。', '{"options": ["送る", "送って", "送った", "送り"], "translation": "Karena lampiran email tidak bisa dibuka, maukah Anda mengirimkannya sekali lagi?", "sentence_template": "メールの添付ファイルが開けないので、もう一度[blank]いただけませんか。"}'::jsonb, '{"selected": "送って"}'::jsonb, 'Sebelum いただけませんか, kata kerja harus diubah ke bentuk て (送る -> 送って).', 1);
        INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
        VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: お客様にお渡しする資料ですので、念のため___していただけませんか。', '{"options": ["ドライブ", "ランチ", "ショッピング", "チェック"], "translation": "Karena ini materi untuk diberikan kepada klien, maukah Anda mengeceknya untuk berjaga-jaga?", "sentence_template": "お客様にお渡しする資料ですので、念のため[blank]していただけませんか。"}'::jsonb, '{"selected": "チェック"}'::jsonb, 'チェックしていただけませんか berarti ''maukah Anda memeriksa/mengeceknya''.', 2);
        INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
        VALUES (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pesan bisnis berikut. Permintaan apa yang disampaikan?', '{"audio_text": "申し訳ありませんが、明日の打ち合わせの時間を三十分ほど遅らせていただけませんか。", "options": [{"id": "opt_1", "text": "Meminta izin mengundurkan jadwal pertemuan besok sekitar 30 menit"}, {"id": "opt_2", "text": "Meminta memajukan jadwal rapat 30 menit lebih awal"}, {"id": "opt_3", "text": "Menginformasikan bahwa rapat berlangsung selama 30 menit"}, {"id": "opt_4", "text": "Membatalkan pertemuan besok secara sepihak"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, '遅らせていただけませんか berarti memohon agar waktu dapat dimundurkan.', 3);
        INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
