        VALUES (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Terima kasih banyak atas kehadiran Anda hari ini."', '{"display_text": "本日はお越しいただき、誠にありがとうございます。", "romaji": "Honjitsu wa okoshi itadaki, makoto ni arigatou gozaimasu.", "phonetic_breakdown": ["hon-ji-tsu-wa", "o-ko-shi", "i-ta-da-ki", "ma-ko-to-ni", "a-ri-ga-tou", "go-za-i-ma-su"]}'::jsonb, '{"expected_transcript": "本日はお越しいただき、誠にありがとうございます。"}'::jsonb, 'Ungkapan penyambutan resmi ini memadukan お越しいただく dengan 誠にありがとうございます.', 8);
