        VALUES (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pengumuman persiapan rapat berikut. Bagaimana kondisi ruang rapat?', '{"audio_text": "会議室に人数分の資料と飲み物が用意してありますので、そのままお使いください。", "options": [{"id": "opt_1", "text": "Materi dan minuman sesuai jumlah peserta sudah disiapkan di ruang rapat"}, {"id": "opt_2", "text": "Ruang rapat belum dibersihkan sejak kemarin"}, {"id": "opt_3", "text": "Peserta harus menyiapkan materi dan minuman sendiri"}, {"id": "opt_4", "text": "Jumlah minuman di ruang rapat masih kurang"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, '用意してあります menunjukkan persiapan yang sudah sengaja dilakukan.', 2);
