        VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Dalam bulan ini harus menyerahkan surat keterangan domisili ke balai kota."', '{"tokens": ["なりません。", "が", "住民票を", "市役所へ", "今月中に", "提出しなければ", "提出します。"], "target_translation": "Dalam bulan ini harus menyerahkan surat keterangan domisili ke balai kota.", "romaji": "Kongetsuchuu ni juuminhyou o shiyakusho e teishutsu shinakereba narimasen."}'::jsonb, '["今月中に", "住民票を", "市役所へ", "提出しなければ", "なりません。"]'::jsonb, '～なければなりません menyatakan kewajiban resmi.', 3);
