        VALUES (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: どんなに忙しくても、朝ごはんだけは抜か___ようにしています。', '{"options": ["ない", "なくて", "ず", "なかった"], "translation": "Sesibuk apa pun, saya berusaha agar tidak melewatkan sarapan.", "sentence_template": "どんなに忙しくても、朝ごはんだけは抜か[blank]ようにしています。"}'::jsonb, '{"selected": "ない"}'::jsonb, '抜く -> 抜かない + ようにしています.', 2);
