        INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
        VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Untuk mengurangi sampah, saya membiasakan membawa tas belanja sendiri."', '{"tokens": ["持ち歩く", "ように", "ために、", "マイバッグを", "減らす", "しています。", "持ち歩いた", "へ", "ゴミを"], "target_translation": "Untuk mengurangi sampah, saya membiasakan membawa tas belanja sendiri.", "romaji": "Gomi o herasu tame ni, maibaggu o mochiaruku you ni shite imasu."}'::jsonb, '["ゴミを", "減らす", "ために、", "マイバッグを", "持ち歩く", "ように", "しています。"]'::jsonb, '持ち歩く (membawa ke mana-mana) + ようにしています.', 4);
