        INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
        VALUES (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Berbeda dengan sikapnya yang keras pada diri sendiri, dia sangat baik kepada orang lain."', '{"tokens": ["自分に", "厳しいのに", "他人には", "優しいです。", "対して、", "おかげで、", "とても", "を", "彼は"], "target_translation": "Berbeda dengan sikapnya yang keras pada diri sendiri, dia sangat baik kepada orang lain.", "romaji": "Kare wa jibun ni kibishii no ni taishite, tanin ni wa totemo yasashii desu."}'::jsonb, '["彼は", "自分に", "厳しいのに", "対して、", "他人には", "とても", "優しいです。"]'::jsonb, '厳しいのに対して mengontraskan dua sisi kepribadian.', 3);
